import{z as B,x as l,o as A,c as p,q as i,j as o,D as e,d as t,s as n,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"两基金分离","description":"","frontmatter":{"title":"两基金分离","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/two-fund-separation.md","filePath":"econ/two-fund-separation.md","lastUpdated":1791413859000}'),d={name:"econ/two-fund-separation.md"};function m(T,a,f,u,h,C){const r=l("Mermaid");return A(),p("div",null,[a[2]||(a[2]=i('<h1 id="两基金分离" tabindex="-1">两基金分离 <a class="header-anchor" href="#两基金分离" aria-label="Permalink to &quot;两基金分离&quot;">​</a></h1><div class="epigraph"><p>有一张无风险债券时，均值方差菜单上的每个人都只在「现金」与**同一**切点风险基金之间配比——分的是风险承担，不是各挑各的股票。</p><footer>—— 据 Tobin, Liquidity Preference as Behavior Towards Risk, Review of Economic Studies, 1958；Markowitz, Journal of Finance, 1952 整理</footer></div><p><a href="/econ/mean-variance-eu">上一课</a>标明 \\(V(\\mu,\\sigma)\\) 等于 \\(\\mathbb{E}u\\) 仅在二次效用或椭圆/正态族上。本课不重写那两条许可证，也不把二次的 IARA 再批一遍。缺口是：在许可证<strong>内部</strong>，菜单若再加一张无风险资产，最优解塌成两个基金的组合。Tobin 分离是这条几何，不是组合实证，也不是市场组合已经被持有。后课 CAPM 才问切点是否等于市场；本课停在个人问题上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均值方差合法之后，可行集是 \\((\\mu,\\sigma)\\) 平面上的一条边界。没有无风险资产时，有效集是双曲线前沿，不同厌恶程度的人选前沿上不同的点，持仓结构可以完全不同。缺口是加上收益确定的债券 \\(r_f\\)：从 \\((0,r_f)\\) 向风险资产前沿做切线，切点 \\(T\\) 是<strong>唯一</strong>的风险基金。任意均值方差决策者的最优都是 \\(\\theta T+(1-\\theta)\\) 的无风险，只 \\(\\theta\\) 随厌恶而变。</p><p>这就是两基金：无风险 + \\(T\\)。Tobin 用它解释「流动性偏好」：利率变，沿这条线移动的是风险承担，不必每人重算协方差。本课不估计切点权重，不把 \\(T\\) 叫市场组合。</p><p><span class="marginnote">数字实例：切点基金 \\(T\\) 由 30% 股票、70% 债券组成。胆小的你拿 40% 现金加 60% 买 \\(T\\)；爱冒险的他借 30% 加杠杆、用 130% 买 \\(T\\)。两人风险资产里股票与债券的比例都是 30:70——差别只在「放多少进去」，不在「放什么」。</span></p><h3 id="分离不是-capm-也不是限价簿" tabindex="-1">分离不是 CAPM，也不是限价簿 <a class="header-anchor" href="#分离不是-capm-也不是限价簿" aria-label="Permalink to &quot;分离不是 CAPM，也不是限价簿&quot;">​</a></h3><p>切点 \\(T\\) 由风险资产的 \\((\\mu,\\Sigma)\\) 与 \\(r_f\\) 决定，与偏好无关——这是分离。CAPM 还要相同信念、市场出清，才把 \\(T\\) 等于市值加权组合。本课没有出清。量化栏的组合与报价更不是这里的对象：这里没有订单，只有给定分布族上的 \\(V(\\mu,\\sigma)\\)。</p><p><span class="marginnote">没有无风险资产时，Markowitz 前沿上任意两点张成整条有效集：那是「两风险基金」形式。Tobin 的工作例子是有 \\(r_f\\) 的那一条，更干净。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在合法的 MV 菜单上画图。风险资产的最小方差前沿给定；过 \\(r_f\\) 的切线是新的有效集（资本配置线）。一阶条件：风险基金内部的相对权重使夏普比最大，与 \\(r_A\\) 无关；\\(r_A\\) 只决定切线上的位置。CARA+正态时，绝对风险需求与财富无关，沿切线移动的是 \\(\\theta\\)，与形状课一致。CRRA 一般不在欧氏 \\((\\mu,\\sigma)\\) 里，不要把幂效用塞进 Tobin 图。</p><p>背景风险若不可交易，切点菜单本身被咬断：可交易财富的边际分布不必仍椭圆，上一课的许可证失效，分离不成立。本课主干假定没有这类 \\(\\tilde y\\)，或它已被写进给定的 \\((\\mu,\\Sigma)\\)。</p>',13)),(A(),o(s,null,{default:e(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MV%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9AMV%20%3D%20EU%20%E7%9A%84%E5%88%80%E5%88%83%22%5D%20--%3E%20RF%5B%22%E5%8A%A0%E5%85%A5%E6%97%A0%E9%A3%8E%E9%99%A9%20r_f%22%5D%0A%20%20RF%20--%3E%20T%5B%22%E5%88%87%E7%82%B9%E5%9F%BA%E9%87%91%20T%22%5D%0A%20%20T%20--%3E%20SEP%5B%22%E6%AF%8F%E4%BA%BA%EF%BC%9A%CE%B8%20T%20%2B%20(1-%CE%B8)%20%E7%8E%B0%E9%87%91%22%5D%0A%20%20SEP%20--%3E%20NOT%5B%22%E6%9C%AC%E8%AF%BE%E4%B8%8D%E5%88%B0%E5%B8%82%E5%9C%BA%E5%87%BA%E6%B8%85%22%5D%0A%20%20NOT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%E5%8D%A0%E4%BC%98%EF%BC%9A%E7%A6%BB%E5%BC%80%20(%CE%BC%2C%CF%83)%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课不引入 \\(\\beta\\)、样本协方差或回测。那些是定价课与量化栏。这里只问：许可证内部，有效需求的维度为何降到一。共同信念一旦放松，每人一条切线，公共 \\(T\\) 消失——那是后课 CAPM 对照，不是本课的默认。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"为什么只剩一个风险基金：椭圆族里，分散只通过协方差矩阵发生，前沿上每一点是某一影子价格下的切点。引入 \\(r_f\\) 之后，所有人面对同一条从 \\(r_f\\) 出发的直线，最陡的那条被所有人共用。厌恶程度改的是在直线上走多远，不改风险篮子内部的比例。二次效用给出同一几何，但 IARA 让 \\(\\theta\\) 随财富下降，与 DARA 主干不合——几何仍分离，比较静态难看。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像自助餐台上同一锅汤，辣度固定；有人舀半碗、有人舀两碗。辣度（风险篮子的成分）不由食客决定，舀多少（风险承担）才由各自胃口决定——分离说的就是这两件事可以分开。")],-1)),(A(),o(s,null,{default:e(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20RF%5B%22%E6%97%A0%E9%A3%8E%E9%99%A9%E5%88%A9%E7%8E%87%20r_f%20%E7%9A%84%E7%82%B9%22%5D%20--%3E%20CAL%5B%22%E8%BF%87%20r_f%20%E7%9A%84%E6%9C%80%E9%99%A1%E5%88%87%E7%BA%BF%3A%20%E8%B5%84%E6%9C%AC%E9%85%8D%E7%BD%AE%E7%BA%BF%22%5D%0A%20%20CAL%20--%3E%20T%5B%22%E5%88%87%E7%82%B9%E5%9F%BA%E9%87%91%20T%3A%20%E5%86%85%E9%83%A8%E6%9D%83%E9%87%8D%E4%B8%8E%E5%81%8F%E5%A5%BD%E6%97%A0%E5%85%B3%22%5D%0A%20%20T%20--%3E%20A%5B%22%E8%83%86%E5%B0%8F%E5%9E%8B%3A%20%E4%B8%80%E9%83%A8%E5%88%86%E7%8E%B0%E9%87%91%2C%20%E4%B8%80%E9%83%A8%E5%88%86%E4%B9%B0%20T%22%5D%0A%20%20T%20--%3E%20B%5B%22%E8%83%86%E5%A4%A7%E5%9E%8B%3A%20%E5%80%9F%E9%92%B1%E5%8A%A0%E6%9D%A0%E6%9D%86%2C%20%E5%85%A8%E6%8A%BC%20T%22%5D%0A%20%20A%20--%3E%20SAME%5B%22%E4%B8%A4%E4%BA%BA%E9%A3%8E%E9%99%A9%E7%AF%AE%E5%AD%90%E7%9A%84%E6%88%90%E5%88%86%E5%AE%8C%E5%85%A8%E7%9B%B8%E5%90%8C%22%5D%0A%20%20B%20--%3E%20SAME%0A%20%20SAME%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%3A%20%E5%81%8F%E5%A5%BD%E5%8F%AA%E5%86%B3%E5%AE%9A%E7%BA%BF%E4%B8%8A%E7%9A%84%E4%BD%8D%E7%BD%AE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>与两期确定消费的对比：那里分离是 Fisher 的生产/消费；这里分离是风险/无风险。都是「先选共同的技术或基金，再按偏好切一刀」。不要把 \\(r_f\\) 写成闲暇工资。</p><p><span class="marginnote">Tobin 1958 针对 Keynes 的流动性偏好：利率通过风险承担起作用，不是通过非理性窖藏。引用不要写成拒绝 vNM，也不要写成交易微观结构。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>异质信念：每人一条切线，基金不再公共。卖空约束、不可分股票，切点不可复制。非椭圆、偏度、跳跃，回到一般 \\(\\mathbb{E}u\\)，分离没有定义——下一课随机占优正是离开两个数字。不完全市场加上背景风险，可交易基金无法复制最优，分离只在张成子空间上像那么回事。</p><p>也不要把「人人持有同一基金」写成经验事实。本课是刀刃上的个人最优，不是持仓数据。后课若见到 CAPM，先问信念是否已被设成相同；本课没有问。</p><p><span class="marginnote">常见误区：初学者容易以为「人人持有同一只基金」在描述股市的真实持仓。实际上它是给定相同信念与均值方差偏好时的个人最优结论——现实中信念各异、约束丛生，公共切点只是理论基准。</span></p><p>切点权重的公式属于许可证内部的算法：\\(T\\propto \\Sigma^{-1}(\\mu-r_f\\mathbf{1})\\)（再归一）。写出它不等于去做样本 \\(\\Sigma\\) 的实证。\\(\\theta\\) 由 \\(r_A\\) 或二次的厌恶参数决定；CARA+正态下 \\(\\theta\\) 与财富无关，CRRA 若不在该刀刃上就不要套这条公式。下一课随机占优离开 \\((\\mu,\\sigma)\\)，分离没有定义。</p><p>后课默认：均值方差加无风险资产，则两基金分离；切点不是市场组合，除非另加入出清。一般 EU 不分离。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MV 许可证内部、有 \\(r_f\\) 时，最优是无风险加唯一切点基金。</li><li>\\(\\theta\\) 随厌恶（与财富形状）变；篮子内部权重与偏好无关。</li><li>这不是 CAPM，不是组合实证，也不是报价机制。</li><li>无 \\(r_f\\) 时是两风险基金张成前沿；信念一散，公共基金消失。</li><li>出处：Tobin, <em>Review of Economic Studies</em>, 1958；Markowitz, <em>Journal of Finance</em>, 1952。</li></ul>',10))])}const c=B(d,[["render",m]]);export{D as __pageData,c as default};
